const resetFailedTranscodeItems = `-- name: ResetFailedTranscodeItems :exec
UPDATE transcode_item SET state = 'needed', attempts = 0, pass = 0, interrupted = 0, failure_code = '', last_error = '', updated_at = ?
WHERE state = 'failed' AND target_id = ?
`

type ResetFailedTranscodeItemsParams struct {
	UpdatedAt int64
	TargetID  int64
}

// A setup save is a new chance: every failed item of the target starts again.
func (q *Queries) ResetFailedTranscodeItems(ctx context.Context, arg ResetFailedTranscodeItemsParams) error {
	_, err := q.db.ExecContext(ctx, resetFailedTranscodeItems, arg.UpdatedAt, arg.TargetID)
	return err
}

